const LIMITE_POR_HORA = 20;
let b = $('Lead chega (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const usos = Number(Object.values($input.first().json)[0]) || 0;
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const id = String(b.id || '');
const erro = m => [{ json: { valido: false, erro: m } }];
if (!/^[a-z0-9-]{4,80}$/.test(id)) return erro('Página inválida.');
if (usos > LIMITE_POR_HORA) return erro('Muitos envios. Tente mais tarde.');

// Descobre o que é nome, telefone, e-mail e mensagem pelo rótulo do campo
const campos = {};
for (const [k, v] of Object.entries(b.campos && typeof b.campos === 'object' ? b.campos : {}).slice(0, 12)) campos[limpa(k, 40)] = limpa(v, 600);
const acha = re => { const k = Object.keys(campos).find(x => re.test(x.normalize('NFD').replace(/[̀-ͯ]/g, ''))); return k ? campos[k] : ''; };
const nome = acha(/nome|name/i).slice(0, 60);
let fone = acha(/whats|telefone|celular|fone|phone|contato/i).replace(/\D/g, '');
if (!fone) {
  const m = Object.values(campos).join(' ').match(/(?:\+?55\s?)?\(?\d{2}\)?\s?9?\d{4}[-.\s]?\d{4}/);
  if (m) fone = m[0].replace(/\D/g, '');
}
if (fone.length === 10 || fone.length === 11) fone = '55' + fone;
if (fone.length < 12 || fone.length > 13) fone = '';
const emailBruto = acha(/e-?mail/i);
const email = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(emailBruto) ? emailBruto.toLowerCase() : '';
const usados = new Set([nome, emailBruto].filter(Boolean));
const mensagem = acha(/mensag|message|assunto|precisa|conte|duvida|pedido|obs/i) ||
  Object.values(campos).filter(v => !usados.has(v) && v.replace(/\D/g, '').length < 10).sort((a, c) => c.length - a.length)[0] || '';
if (!nome && !fone && !email && mensagem.length < 3) return erro('Formulário vazio.');

const eng = b.engajamento || {};
const lead = {
  lead: 'ld' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
  pagina_id: id, nome, whatsapp: fone, email, mensagem: mensagem.slice(0, 600), campos,
  origem: limpa(b.origem, 40) || 'direto',
  pagina: { titulo: limpa(b.pagina && b.pagina.titulo, 120), descricao: limpa(b.pagina && b.pagina.descricao, 300), url: limpa(b.pagina && b.pagina.url, 300) },
  engajamento: { segundos: Math.min(Number(eng.segundos) || 0, 36000), rolagem: Math.min(Number(eng.rolagem) || 0, 100), cliques: Math.min(Number(eng.cliques) || 0, 999), voltou: !!eng.voltou },
  criadoEm: new Date().toISOString(),
};
return [{ json: { valido: true, lead } }];

