let pagina = null;
try { pagina = JSON.parse($('Lê dados da página').first().json.status || 'null'); } catch (e) {}
const ia = parseJSON($input.first().json.output ?? '');
const limpa = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const e = lead.engajamento;

// Sinais objetivos, que não dependem da IA
let bonus = 0; const sinais = [];
if (lead.whatsapp) { bonus += 10; sinais.push('deixou WhatsApp'); }
if (e.rolagem >= 75) { bonus += 8; sinais.push(`leu ${e.rolagem}% da página`); }
if (e.segundos >= 60) { bonus += 5; sinais.push(`ficou ${Math.round(e.segundos / 60)} min`); }
if (e.voltou) { bonus += 7; sinais.push('voltou à página'); }

let nota, usouIA = false;
if (ia && Number.isFinite(Number(ia.nota))) {
  usouIA = true;
  nota = Math.round(Number(ia.nota) * 0.8 + bonus);
} else {
  const temIntencao = /orçamento|orcamento|preço|preco|valor|agendar|marcar|quanto|contratar|comprar|disponib/i.test(lead.mensagem);
  nota = 25 + bonus + (temIntencao ? 25 : 0) + (lead.mensagem.length > 40 ? 10 : 0);
}
const spam = !!(ia && ia.spam) || /^(teste|test|asdf|qwer|aaa+)\b/i.test(lead.mensagem + ' ' + lead.nome) || /https?:\/\//i.test(lead.mensagem);
if (spam) nota = Math.min(nota, 15);
nota = Math.max(0, Math.min(100, nota));
const temperatura = nota >= 70 ? 'quente' : nota >= 40 ? 'morno' : 'frio';

const primeiro = (lead.nome || '').split(' ')[0];
Object.assign(lead, {
  nota, temperatura, spam, usou_ia: usouIA, sinais,
  empresa: (pagina && pagina.empresa) || lead.pagina.titulo || lead.pagina_id,
  intencao: limpa(ia && ia.intencao, 160),
  urgencia: ['alta', 'media', 'baixa'].includes(ia && ia.urgencia) ? ia.urgencia : 'media',
  resumo: limpa(ia && ia.resumo, 240) || 'Classificado pelas regras automáticas (a IA não respondeu).',
  proximo_passo: limpa(ia && ia.proximo_passo, 200) || (lead.whatsapp ? 'Chamar no WhatsApp ainda hoje.' : 'Responder pelo canal informado.'),
  mensagem_sugerida: limpa(ia && ia.mensagem_sugerida, 500) || `Olá${primeiro ? ', ' + primeiro : ''}! Recebemos sua mensagem pelo site e queremos te ajudar. Podemos conversar agora?`,
});
return [{ json: { lead, lead_str: JSON.stringify(lead) } }];

// ⚙️ CONFIGURE AQUI para receber o alerta no WhatsApp (deixe NUMERO vazio para desligar)
const NUMERO = '';                 // quem recebe o alerta, com DDI e DDD. Ex: '5591999998888'
const EVOLUTION_URL = '';          // endereço da sua Evolution API. Ex: 'https://minha-evolution.com'
const INSTANCIA = '';              // nome da instância na Evolution
const APIKEY = '';                 // apikey da instância (o ideal é usar uma credencial do n8n)
const SO_QUENTES_E_MORNOS = true;  // true = não avisa leads frios

const l = $('Nota final').first().json.lead;
const base = String($('Lead chega (POST)').first().json.webhookUrl || '').split('/webhook/')[0];
const ICONE = { quente: '🔥', morno: '🌤️', frio: '❄️' };
const texto = [
  `${ICONE[l.temperatura]} *Novo lead ${l.temperatura.toUpperCase()}* · nota ${l.nota}/100`,
  `🏢 ${l.empresa}`,
  `👤 ${l.nome || 'Sem nome'}${l.whatsapp ? ' · 📱 +' + l.whatsapp : ''}${l.email ? ' · ✉️ ' + l.email : ''}`,
  l.mensagem ? `💬 "${l.mensagem.slice(0, 240)}"` : null,
  `🧠 ${l.resumo}`,
  `👉 ${l.proximo_passo}`,
  `📋 Painel: ${base}/webhook/lp-leads?id=${l.pagina_id}`,
].filter(Boolean).join('\n');

const ligado = !!(NUMERO && EVOLUTION_URL && INSTANCIA && APIKEY) && !l.spam && (!SO_QUENTES_E_MORNOS || l.temperatura !== 'frio');
return [{ json: { ligado, url: `${EVOLUTION_URL.replace(/\/$/, '')}/message/sendText/${INSTANCIA}`, apikey: APIKEY, numero: NUMERO, texto } }];

// 🔐 Senha do painel: troque aqui e também no node "Validar ação"
const SENHA = '<SEGREDO_REMOVIDO>';
const q = $('Painel de leads (GET)').first().json.query || {};
const id = /^[a-z0-9-]{4,80}$/.test(q.id || '') ? q.id : '';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const casca = (titulo, corpo, extra = '') => `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(titulo)}</title>
<style>
:root{--plano:#f6f5f2;--sup:#fff;--tx:#14130f;--tx2:#55534d;--mu:#8a877f;--borda:rgba(20,19,15,.10);--s1:#2a78d6;--trilho:#cde2fb;--quente:#fde4d8;--morno:#fdf1cf;--frio:#dcebfb}
@media (prefers-color-scheme:dark){:root{--plano:#0d0d0d;--sup:#1a1a19;--tx:#f0efec;--tx2:#c3c2b7;--mu:#898781;--borda:rgba(255,255,255,.10);--s1:#3987e5;--trilho:#26303b;--quente:#4a2617;--morno:#45380f;--frio:#16324f}}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--plano);color:var(--tx);padding:22px 14px 60px;line-height:1.45}
.w{max-width:1000px;margin:0 auto}h1{font-size:24px}.sub{color:var(--tx2);font-size:13.5px;margin-top:4px}
.k{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:16px}
.k a{background:var(--sup);border:1px solid var(--borda);border-radius:14px;padding:12px 14px;text-decoration:none;color:var(--tx)}
.k a.on{outline:2px solid var(--s1)}.k span{color:var(--tx2);font-size:13px;font-weight:600}.k b{display:block;font-size:26px}
.lead{background:var(--sup);border:1px solid var(--borda);border-radius:16px;padding:16px 18px;margin-top:12px}
.top{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start}
.nome{font-size:17px;font-weight:650}.meta{color:var(--mu);font-size:12.5px;margin-top:2px}
.tag{display:inline-flex;gap:6px;align-items:center;padding:4px 10px;border-radius:999px;font-weight:650;font-size:13px;color:var(--tx)}
.t-quente{background:var(--quente)}.t-morno{background:var(--morno)}.t-frio{background:var(--frio)}
.nota{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:13px;color:var(--tx2)}
.trilho{flex:1;max-width:260px;height:8px;background:var(--trilho);border-radius:4px;overflow:hidden}.trilho i{display:block;height:100%;background:var(--s1);border-radius:0 4px 4px 0}
.msg{margin-top:10px;padding:10px 12px;border-left:3px solid var(--borda);color:var(--tx);font-size:14.5px;white-space:pre-wrap}
.ia{margin-top:10px;font-size:14px;color:var(--tx2)}.ia b{color:var(--tx)}
.sinais{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.sinais span{font-size:12px;border:1px solid var(--borda);border-radius:999px;padding:2px 9px;color:var(--tx2)}
.acoes{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;align-items:center}
.btn{border:1px solid var(--borda);background:var(--sup);color:var(--tx);border-radius:10px;padding:8px 12px;font:inherit;font-size:13.5px;font-weight:600;cursor:pointer;text-decoration:none}
.btn.zap{background:#25d366;border-color:#25d366;color:#05301a}.btn.sel{background:var(--tx);color:var(--sup);border-color:var(--tx)}
.vazio{color:var(--mu);margin-top:20px}form.login{max-width:360px;margin:70px auto;background:var(--sup);border:1px solid var(--borda);border-radius:18px;padding:26px;text-align:center}
form.login input{width:100%;padding:12px;border-radius:10px;border:1px solid var(--borda);background:var(--plano);color:var(--tx);font:inherit;margin:14px 0 10px}
.erro{color:#d03b3b;font-weight:600;font-size:14px}
</style></head><body><div class="w">${corpo}</div>${extra}</body></html>`;

if (q.senha !== SENHA) {
  return [{ json: { codigo: q.senha ? 401 : 200, html: casca('Leads · acesso', `<form class="login" method="get"><div style="font-size:42px">🎯</div><h1>Painel de leads</h1><p class="sub">Digite a senha do painel</p>
    ${id ? `<input type="hidden" name="id" value="${esc(id)}">` : ''}<input name="senha" type="password" placeholder="Senha" autofocus required aria-label="Senha">
    ${q.senha ? '<p class="erro">Senha incorreta.</p>' : ''}<button class="btn zap" style="width:100%">Entrar</button></form>`) } }];
}

let lista = $('Lê leads').first().json.leads;
if (!Array.isArray(lista)) lista = lista ? [lista] : [];
const situacao = $('Lê situação').first().json.situacao || {};
let leads = lista.map(s => { try { return typeof s === 'string' ? JSON.parse(s) : s; } catch (e) { return null; } }).filter(Boolean).reverse();
if (id) leads = leads.filter(l => l.pagina_id === id);
leads.forEach(l => { l.situacao = situacao[l.lead] || 'novo'; });
const cont = t => leads.filter(l => l.temperatura === t).length;
const filtro = ['quente', 'morno', 'frio'].includes(q.t) ? q.t : '';
const vis = filtro ? leads.filter(l => l.temperatura === filtro) : leads;
const link = t => `?${id ? 'id=' + esc(id) + '&' : ''}senha=${encodeURIComponent(SENHA)}${t ? '&t=' + t : ''}`;
const ICONE = { quente: '🔥 Quente', morno: '🌤️ Morno', frio: '❄️ Frio' };
const SIT = { novo: '🆕 Novo', contatado: '💬 Contatado', fechado: '✅ Fechado', perdido: '✖️ Perdido' };
const fuso = { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' };

const cards = vis.slice(0, 200).map(l => `<article class="lead" data-lead="${esc(l.lead)}">
  <div class="top"><div><div class="nome">${esc(l.nome || 'Sem nome')}</div>
  <div class="meta">${esc(new Date(l.criadoEm).toLocaleString('pt-BR', fuso))} · ${esc(l.empresa)} · origem: ${esc(l.origem)}${l.whatsapp ? ' · 📱 +' + esc(l.whatsapp) : ''}${l.email ? ' · ✉️ ' + esc(l.email) : ''}</div></div>
  <span class="tag t-${l.temperatura}">${ICONE[l.temperatura]}</span></div>
  <div class="nota">Nota <b>${l.nota}</b><span class="trilho" role="meter" aria-valuenow="${l.nota}" aria-valuemin="0" aria-valuemax="100" aria-label="Nota do lead"><i style="width:${l.nota}%"></i></span>${l.spam ? ' · ⚠️ parece spam ou teste' : ''}</div>
  ${l.mensagem ? `<div class="msg">${esc(l.mensagem)}</div>` : ''}
  <div class="ia">🧠 ${esc(l.resumo)}${l.intencao ? `<br><b>Intenção:</b> ${esc(l.intencao)} · <b>Urgência:</b> ${esc(l.urgencia)}` : ''}<br>👉 <b>Próximo passo:</b> ${esc(l.proximo_passo)}</div>
  ${(l.sinais || []).length ? `<div class="sinais">${l.sinais.map(s => `<span>${esc(s)}</span>`).join('')}</div>` : ''}
  <div class="acoes">${l.whatsapp ? `<a class="btn zap" target="_blank" rel="noopener" href="https://wa.me/${esc(l.whatsapp)}?text=${encodeURIComponent(l.mensagem_sugerida)}">📲 Responder com a mensagem sugerida</a>` : ''}
  ${Object.entries(SIT).map(([k, v]) => `<button class="btn ${l.situacao === k ? 'sel' : ''}" data-s="${k}" type="button">${v}</button>`).join('')}</div>
</article>`).join('');

const corpo = `<h1>🎯 Leads${id && leads[0] ? ' · ' + esc(leads[0].empresa) : ''}</h1>
<p class="sub">${id ? 'Leads desta página' : 'Leads de todas as landing pages'} · a IA dá a nota de 0 a 100 e sugere a resposta</p>
<div class="k"><a href="${link('')}" class="${filtro ? '' : 'on'}"><span>Todos</span><b>${leads.length}</b></a>
<a href="${link('quente')}" class="${filtro === 'quente' ? 'on' : ''}"><span>🔥 Quentes</span><b>${cont('quente')}</b></a>
<a href="${link('morno')}" class="${filtro === 'morno' ? 'on' : ''}"><span>🌤️ Mornos</span><b>${cont('morno')}</b></a>
<a href="${link('frio')}" class="${filtro === 'frio' ? 'on' : ''}"><span>❄️ Frios</span><b>${cont('frio')}</b></a>
<a href="${link(filtro)}"><span>💬 Já contatados</span><b>${leads.filter(l => l.situacao !== 'novo').length}</b></a></div>
${cards || '<p class="vazio">Nenhum lead por aqui ainda. Eles chegam quando alguém envia o formulário de contato da landing page.</p>'}`;

const script = `<script>
document.addEventListener('click', function (e) {
  var b = e.target.closest('[data-s]'); if (!b) return;
  var card = b.closest('[data-lead]'); b.disabled = true;
  fetch('/webhook/lp-lead-acao', { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ senha: ${JSON.stringify(SENHA)}, lead: card.getAttribute('data-lead'), situacao: b.getAttribute('data-s') }) })
    .then(function (r) { return r.json(); }).then(function (j) {
      b.disabled = false; if (!j.ok) return alert('Não foi possível salvar.');
      card.querySelectorAll('[data-s]').forEach(function (x) { x.classList.toggle('sel', x === b); });
    }).catch(function () { b.disabled = false; alert('Falha de conexão.'); });
});
</script>`;
return [{ json: { codigo: 200, html: casca('Leads', corpo, script) } }];

// 🔐 Mesma senha do node "Montar painel de leads"
const SENHA = '<SEGREDO_REMOVIDO>';
let b = $('Ação no lead (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const ok = b.senha === SENHA && /^ld[a-z0-9]{6,24}$/.test(String(b.lead || '')) && ['novo', 'contatado', 'fechado', 'perdido'].includes(b.situacao);
return [{ json: { ok, valor: ok ? JSON.stringify({ [b.lead]: b.situacao }) : '' } }];
